import { Test, TestingModule } from '@nestjs/testing';
import { NotFoundException, ForbiddenException } from '@nestjs/common';
import { ProductsService } from '../../../src/products/products.service';
import { PrismaService } from '../../../src/prisma/prisma.service';
import { CreateProductDto, ProductQueryDto } from '../../../src/products/dto/product.dto';
import { Role } from '../../../src/auth/dto/auth.dto';

describe('ProductsService', () => {
  let service: ProductsService;
  let prisma: PrismaService;

  const mockVendor = {
    id: 'vendor-1',
    name: 'Test Vendor',
    userId: 'vendor-user-1',
    user: {
      id: 'vendor-user-1',
      name: 'Vendor User',
      email: 'vendor@example.com',
    },
  };

  const mockProduct = {
    id: 'product-1',
    name: 'Test Product',
    description: 'A test product',
    price: 50,
    stock: 10,
    vendorId: 'vendor-1',
    vendor: mockVendor,
    createdAt: new Date(),
  };

  beforeEach(async () => {
    const mockPrismaService = {
      product: {
        create: jest.fn(),
        findMany: jest.fn(),
        findUnique: jest.fn(),
        update: jest.fn(),
        delete: jest.fn(),
        count: jest.fn(),
      },
      vendor: {
        findUnique: jest.fn(),
      },
    };

    const module: TestingModule = await Test.createTestingModule({
      providers: [
        ProductsService,
        {
          provide: PrismaService,
          useValue: mockPrismaService,
        },
      ],
    }).compile();

    service = module.get<ProductsService>(ProductsService);
    prisma = module.get<PrismaService>(PrismaService);
  });

  it('should be defined', () => {
    expect(service).toBeDefined();
  });

  describe('create', () => {
    const createProductDto: CreateProductDto = {
      name: 'Test Product',
      description: 'A test product',
      price: 50,
      stock: 10,
    };

    it('should create a product successfully', async () => {
      // Arrange
      (prisma.product.create as jest.Mock).mockResolvedValue(mockProduct);

      // Act
      const result = await service.create(createProductDto, 'vendor-1');

      // Assert
      expect(prisma.product.create).toHaveBeenCalledWith({
        data: {
          ...createProductDto,
          vendorId: 'vendor-1',
        },
        include: {
          vendor: {
            include: {
              user: {
                select: {
                  name: true,
                  email: true,
                },
              },
            },
          },
        },
      });
      expect(result).toEqual({
        ...mockProduct,
        vendor: {
          id: mockProduct.vendor.id,
          name: mockProduct.vendor.name,
          user: mockProduct.vendor.user,
        },
      });
    });

    it('should throw error if product creation fails', async () => {
      // Arrange
      (prisma.product.create as jest.Mock).mockRejectedValue(new Error('Database error'));

      // Act & Assert
      await expect(
        service.create(createProductDto, 'vendor-1'),
      ).rejects.toThrow('Database error');
    });
  });

  describe('findAll', () => {
    it('should return all products with pagination', async () => {
      // Arrange
      const products = [mockProduct];
      const total = 1;
      (prisma.product.findMany as jest.Mock).mockResolvedValue(products);
      (prisma.product.count as jest.Mock).mockResolvedValue(total);

      const query: ProductQueryDto = { page: 1, limit: 10 };

      // Act
      const result = await service.findAll(query);

      // Assert
      expect(result.products).toEqual([{
        ...mockProduct,
        vendor: {
          id: mockProduct.vendor.id,
          name: mockProduct.vendor.name,
          user: mockProduct.vendor.user,
        },
      }]);
      expect(result.total).toBe(total);
      expect(result.page).toBe(1);
      expect(result.limit).toBe(10);
    });

    it('should handle search query', async () => {
      // Arrange
      const products = [mockProduct];
      const total = 1;
      (prisma.product.findMany as jest.Mock).mockResolvedValue(products);
      (prisma.product.count as jest.Mock).mockResolvedValue(total);

      const query: ProductQueryDto = { page: 1, limit: 10, search: 'test' };

      // Act
      const result = await service.findAll(query);

      // Assert
      expect(result.products).toEqual([{
        ...mockProduct,
        vendor: {
          id: mockProduct.vendor.id,
          name: mockProduct.vendor.name,
          user: mockProduct.vendor.user,
        },
      }]);
      expect(result.total).toBe(total);
    });
  });

  describe('findOne', () => {
    it('should return a product by id', async () => {
      // Arrange
      (prisma.product.findUnique as jest.Mock).mockResolvedValue(mockProduct);

      // Act
      const result = await service.findOne('product-1');

      // Assert
      expect(prisma.product.findUnique).toHaveBeenCalledWith({
        where: { id: 'product-1' },
        include: {
          vendor: {
            include: {
              user: {
                select: {
                  name: true,
                  email: true,
                },
              },
            },
          },
        },
      });
      expect(result).toEqual({
        ...mockProduct,
        vendor: {
          id: mockProduct.vendor.id,
          name: mockProduct.vendor.name,
          user: mockProduct.vendor.user,
        },
      });
    });

    it('should throw NotFoundException if product not found', async () => {
      // Arrange
      (prisma.product.findUnique as jest.Mock).mockResolvedValue(null);

      // Act & Assert
      await expect(service.findOne('invalid-product')).rejects.toThrow(
        NotFoundException,
      );
    });
  });

  describe('update', () => {
    const updateProductDto = {
      name: 'Updated Product',
      price: 60,
    };

    it('should update a product successfully', async () => {
      // Arrange
      const productForPermissionCheck = {
        id: 'product-1',
        vendorId: 'vendor-1',
        vendor: { userId: 'vendor-user-1' },
      };
      const updatedProduct = { ...mockProduct, ...updateProductDto };

      (prisma.product.findUnique as jest.Mock)
        .mockResolvedValueOnce(productForPermissionCheck)
        .mockResolvedValueOnce(updatedProduct);
      (prisma.product.update as jest.Mock).mockResolvedValue(updatedProduct);

      // Act
      const result = await service.update(
        'product-1',
        updateProductDto,
        'vendor-user-1',
        Role.VENDOR,
      );

      // Assert
      expect(result).toBeDefined();
    });

    it('should throw NotFoundException if product not found', async () => {
      // Arrange
      (prisma.product.findUnique as jest.Mock).mockResolvedValue(null);

      // Act & Assert
      await expect(
        service.update(
          'invalid-product',
          updateProductDto,
          'vendor-user-1',
          Role.VENDOR,
        ),
      ).rejects.toThrow(NotFoundException);
    });

    it('should throw ForbiddenException if vendor tries to update another vendor product', async () => {
      // Arrange
      const productForPermissionCheck = {
        id: 'product-1',
        vendorId: 'vendor-1',
        vendor: { userId: 'vendor-user-1' },
      };
      (prisma.product.findUnique as jest.Mock).mockResolvedValue(productForPermissionCheck);

      // Act & Assert
      await expect(
        service.update(
          'product-1',
          updateProductDto,
          'other-vendor-user',
          Role.VENDOR,
        ),
      ).rejects.toThrow(ForbiddenException);
    });
  });

  describe('remove', () => {
    it('should delete a product successfully', async () => {
      // Arrange
      const productForPermissionCheck = {
        id: 'product-1',
        vendorId: 'vendor-1',
        vendor: { userId: 'vendor-user-1' },
      };

      (prisma.product.findUnique as jest.Mock).mockResolvedValue(productForPermissionCheck);
      (prisma.product.delete as jest.Mock).mockResolvedValue(mockProduct);

      // Act
      await service.remove('product-1', 'vendor-user-1', Role.VENDOR);

      // Assert
      expect(prisma.product.delete).toHaveBeenCalledWith({
        where: { id: 'product-1' },
      });
    });

    it('should throw NotFoundException if product not found', async () => {
      // Arrange
      (prisma.product.findUnique as jest.Mock).mockResolvedValue(null);

      // Act & Assert
      await expect(
        service.remove('invalid-product', 'vendor-user-1', Role.VENDOR),
      ).rejects.toThrow(NotFoundException);
    });

    it('should throw ForbiddenException if vendor tries to delete another vendor product', async () => {
      // Arrange
      const productForPermissionCheck = {
        id: 'product-1',
        vendorId: 'vendor-1',
        vendor: { userId: 'vendor-user-1' },
      };
      (prisma.product.findUnique as jest.Mock).mockResolvedValue(productForPermissionCheck);

      // Act & Assert
      await expect(
        service.remove('product-1', 'other-vendor-user', Role.VENDOR),
      ).rejects.toThrow(ForbiddenException);
    });
  });
});

