    let service: OrdersService;
    let prisma: PrismaService;
    let notificationsGateway: NotificationsGateway;

    const mockCustomer = {
        id: 'customer-1',
        userId: 'customer-user-1',
        user: {
            id: 'customer-user-1',
            name: 'Customer User',
            email: 'customer@example.com',
