            name: 'Vendor User',
            email: 'vendor@example.com',
        },
    };

    const mockProduct = {
        id: 'product-1',
        name: 'Test Product',
        price: 50,
        stock: 10,
        vendorId: 'vendor-1',
        vendor: mockVendor,
    };

    const mockOrder = {
        id: 'order-1',
        customerId: 'customer-1',
        total: 100,
        status: 'PENDING',
        createdAt: new Date(),
