            product: {
                findMany: jest.fn(),
                update: jest.fn(),
            },
            order: {
                create: jest.fn(),
                findMany: jest.fn(),
                findUnique: jest.fn(),
                update: jest.fn(),
            },
            orderItem: {
                createMany: jest.fn(),
            },
            customer: {
                findUnique: jest.fn(),
            },
            vendor: {
                findUnique: jest.fn(),
            },
            $transaction: jest.fn(),
