        });

        it('should throw NotFoundException if customer profile not found', async () => {
            // Arrange
            (prisma.customer.findUnique as jest.Mock).mockResolvedValue(null);

            // Act & Assert
            await expect(
                service.findAll('invalid-customer', Role.CUSTOMER),
            ).rejects.toThrow(NotFoundException);
        });
    });

    describe('findOne', () => {
        it('should return order by id', async () => {
            // Arrange
            (prisma.order.findUnique as jest.Mock).mockResolvedValue(mockOrder);

            // Act
            const result = await service.findOne('order-1');

            // Assert
            expect(result).toEqual(mockOrder);
            expect(prisma.order.findUnique).toHaveBeenCalledWith({
                where: { id: 'order-1' },
                include: expect.any(Object),
            });
        });

        it('should throw NotFoundException if order not found', async () => {
            // Arrange
            (prisma.order.findUnique as jest.Mock).mockResolvedValue(null);

            // Act & Assert
            await expect(service.findOne('invalid-order')).rejects.toThrow(
                NotFoundException,
            );
        });
    });

    describe('updateStatus', () => {
        const updateStatusDto: UpdateOrderStatusDto = {
            status: 'COMPLETED',
        };

        it('should update order status successfully', async () => {
            // Arrange
            const updatedOrder = { ...mockOrder, status: 'COMPLETED' };
            (prisma.order.findUnique as jest.Mock).mockResolvedValue(mockOrder);
            (prisma.order.update as jest.Mock).mockResolvedValue(updatedOrder);
            jest.spyOn(service, 'findOne').mockResolvedValue(updatedOrder as any);

            // Act
            const result = await service.updateStatus('order-1', updateStatusDto, Role.ADMIN);

            // Assert
            expect(result).toEqual(updatedOrder);
            expect(prisma.order.update).toHaveBeenCalledWith({
                where: { id: 'order-1' },
                data: { status: 'COMPLETED' },
            });
        });

        it('should throw ForbiddenException if not admin', async () => {
