import { Test, TestingModule } from '@nestjs/testing';
import { JwtService } from '@nestjs/jwt';
import { ConfigService } from '@nestjs/config';
import { NotificationsGateway } from '../../../src/notifications/notifications.gateway';

describe('NotificationsGateway', () => {
    let gateway: NotificationsGateway;
    let jwtService: JwtService;

    const mockJwtPayload = {
        sub: 'user-1',
        email: 'test@example.com',
        role: 'CUSTOMER',
    };

    beforeEach(async () => {
        const mockJwtService = {
            verifyAsync: jest.fn(),
        };

        const mockConfigService = {
            get: jest.fn().mockReturnValue('test-secret'),
        };

        const module: TestingModule = await Test.createTestingModule({
            providers: [
                NotificationsGateway,
                {
                    provide: JwtService,
                    useValue: mockJwtService,
                },
                {
                    provide: ConfigService,
                    useValue: mockConfigService,
                },
            ],
        }).compile();

        gateway = module.get<NotificationsGateway>(NotificationsGateway);
        jwtService = module.get<JwtService>(JwtService);

        // Mock the server
        gateway.server = {
            to: jest.fn().mockReturnThis(),
            emit: jest.fn(),
        } as any;
    });

    describe('handleConnection', () => {
        it('should handle successful connection with auth token', async () => {
            // Arrange
            const mockSocket = {
                id: 'socket-1',
                handshake: {
                    auth: { token: 'valid-token' },
                    headers: {},
                },
                emit: jest.fn(),
                join: jest.fn(),
                disconnect: jest.fn(),
            };
            (jwtService.verifyAsync as jest.Mock).mockResolvedValue(mockJwtPayload);

            // Act
            await gateway.handleConnection(mockSocket as any);

            // Assert
            expect(jwtService.verifyAsync as jest.Mock).toHaveBeenCalledWith(
                'valid-token',
                {
                    secret: 'test-secret',
                } as any,
            );
            expect(mockSocket.user).toEqual({
                id: 'user-1',
                email: 'test@example.com',
                role: 'CUSTOMER',
            });
            expect(mockSocket.join).toHaveBeenCalledWith('user:user-1');
            expect(mockSocket.emit).toHaveBeenCalledWith('connected', {
                message: 'Successfully connected to notifications',
                user: mockSocket.user,
            } as any);
        });

        it('should handle connection with authorization header', async () => {
            // Arrange
            const mockSocket = {
                handshake: {
                    headers: { authorization: 'Bearer header-token' },
                },
                emit: jest.fn(),
                join: jest.fn(),
                disconnect: jest.fn(),
            };
            (jwtService.verifyAsync as jest.Mock).mockResolvedValue(mockJwtPayload);

            // Act
            await gateway.handleConnection(mockSocket as any);

            // Assert
            expect(jwtService.verifyAsync as jest.Mock).toHaveBeenCalledWith(
                'header-token',
                {
                    secret: 'test-secret',
                } as any,
            );
        });

        it('should disconnect if no token provided', async () => {
            // Arrange
            const mockSocket = {
                handshake: {
                    headers: {},
                },
                disconnect: jest.fn(),
            };

            // Act
            await gateway.handleConnection(mockSocket as any);

            // Assert
            expect(mockSocket.disconnect).toHaveBeenCalled();
            expect(jwtService.verifyAsync as jest.Mock).not.toHaveBeenCalled();
        });

        it('should disconnect if token is invalid', async () => {
            // Arrange
            const mockSocket = {
                handshake: {
                    auth: { token: 'invalid-token' },
                    headers: {},
                },
                disconnect: jest.fn(),
                emit: jest.fn(),
            };
            (jwtService.verifyAsync as jest.Mock).mockRejectedValue(
                new Error('Invalid token'),
            );

            // Act
            await gateway.handleConnection(mockSocket as any);

            // Assert
            expect(mockSocket.disconnect).toHaveBeenCalled();
            expect(mockSocket.emit).not.toHaveBeenCalled();
        });
    });

    describe('handleDisconnect', () => {
        it('should handle disconnect for authenticated user', () => {
            // Arrange
            const mockSocket = {
                user: {
                    id: 'user-1',
                    email: 'test@example.com',
                    role: 'CUSTOMER',
                },
            };

            // Simulate user connection first
            gateway['connectedUsers'].set('user-1', mockSocket as any);

            // Act
            gateway.handleDisconnect(mockSocket as any);

            // Assert
            expect(gateway['connectedUsers'].has('user-1')).toBe(false);
        });

        it('should handle disconnect for unauthenticated user', () => {
            // Arrange
            const mockSocket = {};

            // Act
            gateway.handleDisconnect(mockSocket as any);

            // Assert - Should not throw error
            expect(gateway['connectedUsers'].size).toBe(0);
        });
    });

    describe('sendOrderStatusNotification', () => {
        it('should send order status notification to specific user', () => {
            // Arrange
            const notification = {
                orderId: 'order-1',
                status: 'SHIPPED',
                message: 'Your order has been shipped',
            };

            // Act
            gateway.sendOrderStatusNotification('user-1', notification);

            // Assert
            expect(gateway.server.to as jest.Mock).toHaveBeenCalledWith(
                'user:user-1',
            );
            expect(gateway.server.emit as jest.Mock).toHaveBeenCalledWith(
                'orderStatusChange',
                notification,
            );
        });
    });

    describe('sendNotificationToUsers', () => {
        it('should send notification to multiple users', () => {
            // Arrange
            const userIds = ['user-1', 'user-2', 'user-3'];
            const notification = {
                type: 'promotion',
                message: 'Special offer available!',
            };

            // Act
            gateway.sendNotificationToUsers(userIds, notification);

            // Assert
            expect(gateway.server.to as jest.Mock).toHaveBeenCalledTimes(3);
            expect(gateway.server.to as jest.Mock).toHaveBeenCalledWith('user:user-1');
            expect(gateway.server.to as jest.Mock).toHaveBeenCalledWith('user:user-2');
            expect(gateway.server.to as jest.Mock).toHaveBeenCalledWith('user:user-3');
            expect(gateway.server.emit as jest.Mock).toHaveBeenCalledTimes(3);
            expect(gateway.server.emit as jest.Mock).toHaveBeenCalledWith(
                'notification',
                notification,
            );
        });
    });

    describe('sendNotificationToRole', () => {
        it('should send notification to all users with specific role', () => {
            // Arrange
            const mockSocket1 = {
                user: { id: 'user-1', email: 'customer@test.com', role: 'CUSTOMER' },
                emit: jest.fn(),
            };
            const mockSocket2 = {
                user: { id: 'user-2', email: 'vendor@test.com', role: 'VENDOR' },
                emit: jest.fn(),
            };
            const mockSocket3 = {
                user: { id: 'user-3', email: 'customer2@test.com', role: 'CUSTOMER' },
                emit: jest.fn(),
            };

            gateway['connectedUsers'].set('user-1', mockSocket1 as any);
            gateway['connectedUsers'].set('user-2', mockSocket2 as any);
            gateway['connectedUsers'].set('user-3', mockSocket3 as any);

            const notification = {
                type: 'announcement',
                message: 'Important announcement for customers',
            };

            // Act
            gateway.sendNotificationToRole('CUSTOMER', notification);

            // Assert
            expect(mockSocket1.emit).toHaveBeenCalledWith('notification', notification);
            expect(mockSocket2.emit).not.toHaveBeenCalled();
            expect(mockSocket3.emit).toHaveBeenCalledWith('notification', notification);
        });
    });

    describe('getConnectedUsers', () => {
        it('should return array of connected user IDs', () => {
            // Arrange
            const mockSocket1 = { user: { id: 'user-1' } };
            const mockSocket2 = { user: { id: 'user-2' } };

            gateway['connectedUsers'].set('user-1', mockSocket1 as any);
            gateway['connectedUsers'].set('user-2', mockSocket2 as any);

            // Act
            const result = gateway.getConnectedUsers();

            // Assert
            expect(result).toEqual(['user-1', 'user-2']);
        });

        it('should return empty array when no users connected', () => {
            // Act
            const result = gateway.getConnectedUsers();

            // Assert
            expect(result).toEqual([]);
        });
    });

    describe('isUserConnected', () => {
        it('should return true if user is connected', () => {
            // Arrange
            const mockSocket = { user: { id: 'user-1' } };
            gateway['connectedUsers'].set('user-1', mockSocket as any);

            // Act
            const result = gateway.isUserConnected('user-1');

            // Assert
            expect(result).toBe(true);
        });

        it('should return false if user is not connected', () => {
            // Act
            const result = gateway.isUserConnected('user-1');

            // Assert
            expect(result).toBe(false);
        });
    });
});

import { Test, TestingModule } from '@nestjs/testing';
import { NotFoundException } from '@nestjs/common';
import { ChatService } from '../../../src/chat/chat.service';
import { PrismaService } from '../../../src/prisma/prisma.service';
import { SendMessageDto, ChatType, ChatQueryDto } from '../../../src/chat/dto/chat.dto';
import { Role } from '../../../src/auth/dto/auth.dto';

describe('ChatService', () => {
  let service: ChatService;
  let prisma: PrismaService;

  const mockUser = {
    id: 'user-1',
    name: 'Test User',
    email: 'test@example.com',
    role: Role.CUSTOMER,
  };

  const mockReceiver = {
    id: 'vendor-user-1',
    name: 'Vendor User',
    email: 'vendor@example.com',
    role: Role.VENDOR,
  };

  const mockChatMessage = {
    id: 'message-1',
    senderId: 'user-1',
    receiverId: 'vendor-user-1',
    message: 'Hello!',
    chatType: ChatType.DIRECT,
    createdAt: new Date(),
    sender: mockUser,
    receiver: mockReceiver,
  };

  beforeEach(async () => {
    const mockPrismaService = {
      chatMessage: {
        create: jest.fn(),
        findMany: jest.fn(),
      },
      user: {
        findUnique: jest.fn(),
        findFirst: jest.fn(),
      },
      vendor: {
        findUnique: jest.fn(),
      },
    };

    const module: TestingModule = await Test.createTestingModule({
      providers: [
        ChatService,
        {
          provide: PrismaService,
          useValue: mockPrismaService,
        },
      ],
    }).compile();

    service = module.get<ChatService>(ChatService);
    prisma = module.get<PrismaService>(PrismaService);
  });

  it('should be defined', () => {
    expect(service).toBeDefined();
  });

  describe('sendMessage', () => {
    const sendMessageDto: SendMessageDto = {
      receiverId: 'vendor-user-1',
      message: 'Hello!',
      chatType: ChatType.DIRECT,
    };

    it('should send a message successfully', async () => {
      // Arrange
      (prisma.user.findUnique as jest.Mock)
        .mockResolvedValueOnce(mockUser)
        .mockResolvedValueOnce(mockReceiver);
      (prisma.chatMessage.create as jest.Mock).mockResolvedValue(
        mockChatMessage,
      );

      // Act
      const result = await service.sendMessage(sendMessageDto, 'user-1');

      // Assert
      expect(result).toEqual(mockChatMessage);
    });

    it('should throw NotFoundException if receiver not found', async () => {
      // Arrange
      (prisma.user.findUnique as jest.Mock)
        .mockResolvedValueOnce(mockUser)
        .mockResolvedValueOnce(null);

      // Act & Assert
      await expect(
        service.sendMessage(sendMessageDto, 'user-1'),
      ).rejects.toThrow(NotFoundException);
    });
  });

  describe('getChatHistory', () => {
    it('should return chat history between two users', async () => {
      // Arrange
      const messages = [mockChatMessage];
      (prisma.chatMessage.findMany as jest.Mock).mockResolvedValue(messages);

      const query: ChatQueryDto = { page: 1, limit: 50 };

      const expectedResult = [{
        id: mockChatMessage.id,
        senderId: mockChatMessage.senderId,
        receiverId: mockChatMessage.receiverId,
        message: mockChatMessage.message,
        chatType: mockChatMessage.chatType,
        createdAt: mockChatMessage.createdAt,
        sender: mockChatMessage.sender,
        receiver: mockChatMessage.receiver,
      }];

      // Act
      const result = await service.getChatHistory(
        'user-1',
        'vendor-user-1',
        query,
      );

      // Assert
      expect(result).toEqual(expectedResult);
    });
  });
});
